   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="app"></div>

     <script>
       const faqs = [
         {
           question: "Why do cats purr?",
           answers: [
             "Cats often purr when they feel content, but they may also purr when they're nervous, hurt, or trying to calm themselves.",
             "The vibration can be a social signal, a comfort behavior, or part of their healing and self-soothing routine."
           ]
         },
         {
           question: "How much sleep do cats need?",
           answers: [
             "Most cats sleep 12 to 16 hours a day, and kittens or senior cats can sleep even more.",
             "Their bursty hunting instincts mean they conserve energy with long naps between short periods of play."
           ]
         },
         {
           question: "Do indoor cats need exercise?",
           answers: [
             "Yes. Daily play helps indoor cats stay fit, burn energy, and reduce boredom-related behavior.",
             "Use wand toys, puzzle feeders, and short chase sessions to mimic hunting in a safe way."
           ]
         },
         {
           question: "Why do cats bring gifts?",
           answers: [
             "A cat may bring a toy or even a captured object as part of their hunting instinct or social sharing.",
             "It can be a sign that they trust you enough to include you in their world."
           ]
         }
       ];

       function FAQItem({ question, answers }, index) {
         const id = `faq-${index}`;
         return `
           <div class="example" data-faq>
             <h2 class="question">
               <button
                 type="button"
                 class="toggle"
                 aria-expanded="false"
                 aria-controls="${id}"
                 id="${id}-button"
               >
                 <span class="toggle-title">${question}</span>
                 <span class="icon" aria-hidden="true">+</span>
               </button>
             </h2>
             <div class="details" id="${id}">
               ${answers.map((answer) => `<p>${answer}</p>`).join("")}
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <main id="main" class="page">
             <section class="hero" aria-labelledby="page-title">
               <p class="eyebrow">Cat FAQ</p>
               <h1 id="page-title">Curious questions about cats</h1>
               <p class="intro">
                 A compact, readable FAQ with disclosure panels that start collapsed and expand on demand.
               </p>
               <div class="faq" aria-label="Frequently asked questions about cats">
                 ${faqs.map(FAQItem).join("")}
               </div>
             </section>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = App();

       document.querySelectorAll("[data-faq]").forEach((item) => {
         const button = item.querySelector(".toggle");
         const panel = item.querySelector(".details");
         const icon = item.querySelector(".icon");

         button.setAttribute("aria-expanded", "false");
         panel.hidden = true;

         const setOpen = (open) => {
           button.setAttribute("aria-expanded", String(open));
           panel.hidden = !open;
           item.toggleAttribute("open", open);
           if (icon) icon.textContent = open ? "×" : "+";
         };

         button.addEventListener("click", () => {
           const open = button.getAttribute("aria-expanded") === "true";
           setOpen(!open);
         });

         button.addEventListener("keydown", (event) => {
           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
             setOpen(false);
             button.focus();
           }
         });
       });
     </script>
   </body>
